var update = (initUrl, initToken) => {
    try {
        var [novelUrl, chapterId] = initUrl.split('/chapter/');
        var url = novelUrl.replace('/novel/', '/user/read-history/');
        var {Authorization: token} = JSON.parse(initToken);
        return Packages.org.jsoup.Jsoup.connect(url).method(Packages.org.jsoup.Connection.Method.PUT).header("Authorization", token).requestBody(chapterId).execute().body();
    } catch (e) {
        return '';
    }
};
var annotate = (paragraphs, chapterUrl) => {
    try {
        var idx = [], texts = [];
        paragraphs.forEach((p, i) => {
            var t = String(p || '');
            if (!t || t.indexOf('<图片>') >= 0) return;
            idx.push(i);
            texts.push(t);
        });
        if (!texts.length) return paragraphs;
        var conn = new java.net.URL('https://static.kksk.io/api/annotate').openConnection();
        conn.setRequestMethod('POST');
        conn.setDoOutput(true);
        conn.setConnectTimeout(5000);
        conn.setReadTimeout(20000);
        conn.setRequestProperty('Content-Type', 'application/json');
        var os = conn.getOutputStream();
        os.write(new java.lang.String(JSON.stringify({paragraphs: texts, chapterUrl: chapterUrl})).getBytes('UTF-8'));
        os.close();
        var code = conn.getResponseCode();
        if (code !== 200) {
            conn.disconnect();
            return paragraphs;
        }
        var reader = new java.io.BufferedReader(new java.io.InputStreamReader(conn.getInputStream(), 'UTF-8'));
        var sb = new java.lang.StringBuilder();
        var line;
        while ((line = reader.readLine()) !== null) sb.append(line);
        reader.close();
        conn.disconnect();
        var resp = JSON.parse(sb.toString());
        if (!resp || !resp.paragraphs || resp.paragraphs.length !== texts.length) return paragraphs;
        var out = paragraphs.slice();
        idx.forEach((oi, k) => { out[oi] = resp.paragraphs[k]; });
        return out;
    } catch (e) {
        return paragraphs;
    }
};
var regex = content => {
    var displayedImages = new Set();
    return JSON.stringify(content).replace(/<图片>(https?:\/\/[^"\s]+)/g, (match, url) => {
        if (displayedImages.has(url)) return '';
        displayedImages.add(url);
        var referer = url.match(/https?:\/\/[^\/]+/)[0].replace(/i\.pximg\.net/, 'www.pixiv.net');
        var headers = JSON.stringify({headers: {Referer: referer}});
        return `<img src="${url},${headers}">`;
    });
};
var format = content => (() => {
    try { var a = JSON.parse(content); return Array.isArray(a) ? a : [a]; }
    catch (e) { return [content]; }
})().map(item => String(item || '').trim()).filter(Boolean)
